SELECT

FROM txwx_sync_task
WHERE del_flag = '0'

    AND task_name LIKE CONCAT('%', #{taskName}, '%')


    AND channel_type = #{channelType}


    AND product_id = #{productId}


    AND channel_id = #{channelId}


    AND account_id = #{accountId}


    AND task_status = #{taskStatus}

ORDER BY create_time DESC
